<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Theme\Application\Policy\Filter;

use Throwable;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Features\Document\Theme\Application\Service\Visibility\ThemeRestrictFilterToVisibility;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TenantAccesible
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(private readonly Context $context)
    {
    }
    public function __invoke(ThemeRestrictFilterToVisibility $event): ThemeRestrictFilterToVisibility
    {
        $this->logDebug("Check TenantAccesible Theme");
        $span = $this->startSpan("Check TenantAccesible Theme");
        try {
            $identity = $this->context->getIdentity();
            if (!($identity->hasScope("platform:global_access"))) {
                $event->with($event->themeFilter->withTenantAccesible($identity->tenant));
            }
            return $event;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
